<script setup>
import {computed,onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {api} from '../bridge/jcefBridge';import PageShell from '../components/common/PageShell.vue';const fields=ref([]);const groups=computed(()=>[{title:'对话输入',desc:'对话输入框的辅助能力',items:fields.value.filter(x=>x.key.startsWith('chat.'))},{title:'模型执行',desc:'模型调用循环、重试与蒸馏并发',items:fields.value.filter(x=>x.key.startsWith('model.max_')||x.key.startsWith('agent.'))},{title:'模型网络',desc:'模型 HTTP 连接、DNS 与请求超时',items:fields.value.filter(x=>x.key.startsWith('model.')&&!x.key.startsWith('model.max_'))},{title:'网页获取',desc:'Web Fetch 的代理、超时和响应大小',items:fields.value.filter(x=>x.key.startsWith('web_fetch.'))}]);async function save(){const values={};fields.value.forEach(x=>values[x.key]=String(x.value));await api('config.save',{values});ElMessage.success('全局设置已保存')}onMounted(async()=>{fields.value=(await api('config.get')).map(x=>({...x,value:x.type==='boolean'?String(x.value)==='true':x.type==='number'?Number(x.value):x.value}))})
</script><template><PageShell title="全局设置"><template #actions><el-button type="primary" @click="save">保存设置</el-button></template><div class="settings-page"><section v-for="g in groups" :key="g.title" class="settings-group"><header><strong>{{g.title}}</strong><p>{{g.desc}}</p></header><div v-for="x in g.items" :key="x.key" class="setting-row"><div><label>{{x.label}}</label><small>{{x.key}}</small></div><el-switch v-if="x.type==='boolean'" v-model="x.value"/><el-input-number v-else-if="x.type==='number'" v-model="x.value"/><el-select v-else-if="x.type==='select'" v-model="x.value" class="setting-select"><el-option v-for="o in x.options||[]" :key="o.value" :value="o.value" :label="o.label"/></el-select><el-input v-else v-model="x.value"/></div></section></div></PageShell></template>
